/* 真实二维码：内联 data URI，零网络请求，首帧即可绘制（同源数据不污染 canvas，可正常导出） */
const QR_DATA = 'data:image/png;base64,';
const QR_IMG = new Image();
QR_IMG.src = QR_DATA;
/* 二维码就绪回调：已解码立即执行，否则等 load / error，失败也放行 */
function whenQrReady(cb) {
  if (QR_IMG.complete && QR_IMG.naturalWidth > 0) { cb(); return; }
  let done = false;
  const fire = () => { if (done) return; done = true; cb(); };
  QR_IMG.addEventListener('load', fire);
  QR_IMG.addEventListener('error', fire);
  if (QR_IMG.decode) QR_IMG.decode().then(fire).catch(fire);
}

function drawQr(ctx, x, y, size, seed) {
  rr(ctx, x - 6, y - 6, size + 12, size + 12, 10);
  ctx.fillStyle = '#fff'; ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.12)'; ctx.lineWidth = 1; ctx.stroke();
  if (QR_IMG.complete && QR_IMG.naturalWidth) { ctx.drawImage(QR_IMG, x, y, size, size); return true; }
  const cells = 9, c = size / cells;
  let s = seed || 7;
  const rnd = () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  ctx.fillStyle = '#EDF1F9';
  for (let i = 0; i < cells; i++) for (let j = 0; j < cells; j++) {
    const corner = (i < 3 && j < 3) || (i < 3 && j > cells - 4) || (i > cells - 4 && j < 3);
    if (corner) { if (i % 2 === 0 || j % 2 === 0) ctx.fillRect(x + j * c, y + i * c, c - 1.5, c - 1.5); }
    else if (rnd() > 0.53) ctx.fillRect(x + j * c, y + i * c, c - 1.5, c - 1.5);
  }
  return false;
}
/* 主绘制：ratio = '3:4' 小红书 | '1:1' 朋友圈 | '9:16' 视频/状态长图 */
function drawShareCard(canvas, fig, pct, scores, ratio) {
  const CFG = {
    '3:4':  { H: 1000, pad: 18, brand: 22, title: 16, name: 52, pct: 72, quote: 28, qlh: 38, chipH: 34, chipF: 20, seal: 94, radarR: 62, labelF: 17, qr: 88,  emblem: 320 },
    '1:1':  { H: 750,  pad: 12, brand: 17, title: 14, name: 40, pct: 50, quote: 22, qlh: 29, chipH: 28, chipF: 17, seal: 66, radarR: 46, labelF: 12, qr: 62,  emblem: 230 },
    '9:16': { H: 1334, pad: 22, brand: 25, title: 19, name: 62, pct: 84, quote: 33, qlh: 45, chipH: 40, chipF: 23, seal: 116, radarR: 80, labelF: 19, qr: 100, emblem: 360 }
  };
  const C = CFG[ratio] || CFG['3:4'];
  const W = 750, H = C.H;
  const st = FIG_STYLE[fig.id] || { em: fig.name[0], a: '#E2B45C', s: '#F7E8E5' };
  const accent = st.a, accentSoft = st.s;
  const dpr = window.devicePixelRatio || 1;
  canvas.width = W * dpr; canvas.height = H * dpr;
  canvas.style.width = '100%'; canvas.style.height = 'auto';
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  const sorted = DIMS.slice().sort((a, b) => scores[b] - scores[a]);
  const strong = sorted[0], weak = sorted[7];
  const plan = [];
  const FONT2 = FONT;

  /* 底：纸色 + 人物专属淡色晕染 */
  ctx.fillStyle = P.bg; ctx.fillRect(0, 0, W, H);
  const wash = ctx.createLinearGradient(0, 0, 0, H * 0.55);
  wash.addColorStop(0, accentSoft); wash.addColorStop(1, 'rgba(7,11,22,0)');
  ctx.fillStyle = wash; ctx.fillRect(0, 0, W, H * 0.55);
  ctx.fillStyle = accent; ctx.fillRect(0, 0, W, ratio === '1:1' ? 9 : 13);

  /* 人物专属水印符号：整张卡的视觉锤 */
  ctx.save();
  ctx.globalAlpha = 0.07;
  ctx.fillStyle = accent;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = '700 ' + C.emblem + 'px ' + FONT2;
  ctx.fillText(st.em, 375, H * (ratio === '1:1' ? 0.52 : 0.5));
  ctx.restore();
  ctx.textBaseline = 'alphabetic';

  const inset = C.pad;
  const footH = ratio === '1:1' ? 92 : 122;
  const footTop = H - inset - footH - 6;
  ctx.strokeStyle = 'rgba(255,255,255,0.10)'; ctx.lineWidth = 1;
  rr(ctx, inset, inset, W - inset * 2, H - inset * 2, 18); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,0.06)';
  rr(ctx, inset + 8, inset + 8, W - (inset + 8) * 2, H - (inset + 8) * 2, 14); ctx.stroke();

  const T = (str, size, color, baseline, weight, align, leftX) => {
    const px = (align === 'left' || align === 'right') ? (leftX || 78) : 375;
    ctx.fillStyle = color;
    ctx.font = (weight || '400') + ' ' + size + 'px ' + FONT2;
    ctx.textAlign = align || 'center';
    ctx.fillText(str, px, baseline);
    const w = ctx.measureText(str).width;
    const x1 = align === 'left' ? px : (align === 'right' ? px - w : px - w / 2);
    const box = { x1: x1, x2: x1 + w, y1: baseline - size * 0.82, y2: baseline + size * 0.24 };
    plan.push(Object.assign({ n: str.slice(0, 8) }, box));
    return box;
  };

  /* 1. 品牌行 */
  T('王 者 荣 耀 人 物 测 试', C.brand, P.ink3, inset + C.brand + (ratio === '1:1' ? 22 : 34));
  let y = inset + C.brand + (ratio === '1:1' ? 22 : 34) + (ratio === '1:1' ? 10 : 14);
  ctx.strokeStyle = 'rgba(255,255,255,0.20)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(347, y); ctx.lineTo(403, y); ctx.stroke();
  plan.push({ n: 'rule', x1: 347, x2: 403, y1: y - 3, y2: y + 3 });

  /* 2. 人物印章（用专属主色） */
  const sealTop = y + (ratio === '1:1' ? 6 : 10);
  drawSeal(ctx, 375, sealTop + C.seal / 2, C.seal, fig.name[0], 16, accent);
  plan.push({ n: 'seal', x1: 375 - C.seal / 2 - 4, x2: 375 + C.seal / 2 + 4, y1: sealTop, y2: sealTop + C.seal + 5 });
  y = sealTop + C.seal;

  /* 3. 称号 + 姓名 */
  const titleBase = y + C.title + (ratio === '1:1' ? 14 : 20);
  T(fig.role + ' · ' + fig.tags[0], C.title, accent, titleBase, '500');
  y = titleBase;
  const nameBase = y + C.name + (ratio === '1:1' ? 10 : 16);
  T(fig.name, C.name, P.ink, nameBase, '700');
  y = nameBase;

  /* 4. 匹配度主视觉 */
  const lbSize = Math.round(C.pct * 0.24);
  const lbBase = y + lbSize + (ratio === '1:1' ? 14 : 22);
  T('八 维 人 格 相 似 度', lbSize, P.ink3, lbBase);
  const pctBase = lbBase + Math.round(lbSize * 0.7) + C.pct * 0.78;
  const pctBox = T(pct + '%', C.pct, accent, pctBase, '700');
  pctBox.y1 = pctBase - C.pct * 0.76; plan[plan.length - 1].y1 = pctBox.y1;
  const ruleY = pctBase - C.pct * 0.33;
  ctx.strokeStyle = accent; ctx.globalAlpha = 0.35; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(pctBox.x1 - 96, ruleY); ctx.lineTo(pctBox.x1 - 26, ruleY); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(pctBox.x2 + 26, ruleY); ctx.lineTo(pctBox.x2 + 96, ruleY); ctx.stroke();
  ctx.globalAlpha = 1;
  y = pctBase + Math.round(C.pct * 0.18) + (ratio === '1:1' ? 14 : 24);

  /* 5. 金句：卡片的情绪中心 */
  ctx.strokeStyle = 'rgba(255,255,255,0.10)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(120, y + 6); ctx.lineTo(630, y + 6); ctx.stroke();
  const qSize = C.quote, qlh = C.qlh;
  ctx.fillStyle = P.ink;
  ctx.font = '500 ' + qSize + 'px ' + FONT2;
  const qBox = wrapText(ctx, '「' + fig.quote + '」', 375, y + qSize + 30, 560, qlh, 'center');
  const quoteBottom = qBox.bottom + Math.round(qSize * 0.3);
  plan.push({ n: 'quote', x1: 95, x2: 655, y1: y + 12, y2: quoteBottom });
  y = quoteBottom + (ratio === '1:1' ? 16 : 24);

  /* 6. 标签行 */
  const chipTop = y + (ratio === '1:1' ? 10 : 14);
  const chipRow = drawChipRow(ctx, [{ text: fig.role, fg: accent, bg: accentSoft }]
    .concat(fig.tags.map(t => ({ text: t, fg: P.ink2, bg: 'rgba(255,255,255,0.07)' }))),
    chipTop + C.chipH / 2, C.chipH, C.chipF);
  plan.push({ n: 'chips', x1: chipRow.left - 4, x2: chipRow.right + 4, y1: chipTop, y2: chipTop + C.chipH });
  y = chipTop + C.chipH;

  /* 6b. 最强 / 最弱（紧贴标签行下方，与页脚彻底解耦） */
  const swSize = Math.round(C.labelF * 1.2);
  const swBase = y + swSize + (ratio === '1:1' ? 12 : 16);
  T('最强 · ' + strong, swSize, accent, swBase, '600', 'left', 122);
  T('最弱 · ' + weak, swSize, P.ink3, swBase, '400', 'right', 628);
  y = swBase + Math.round(swSize * 0.4);

  /* 7. 八维雷达图 + 最强 / 最弱 */
  const ornY = y + (ratio === '1:1' ? 14 : 24);
  drawOrnament(ctx, 375, ornY, ratio === '1:1' ? 100 : 130);
  plan.push({ n: 'ornament', x1: 245, x2: 505, y1: ornY - 8, y2: ornY + 8 });
  const extent = C.radarR + C.labelF * 1.85 + 4;
  const gapAfterOrn = ratio === '1:1' ? 14 : 20;
  const tagBlock = 0;
  const maxExtent = Math.floor((footTop - ornY - gapAfterOrn - tagBlock) / 2);
  const R = Math.max(34, Math.min(C.radarR, maxExtent - C.labelF * 1.85 - 4));
  const extent2 = R + C.labelF * 1.85 + 4;
  const radarCy = ornY + gapAfterOrn + extent2;
  ctx.save();
  const radarBox = drawRadarShapeAccent(ctx, 375, radarCy, R, scores, C.labelF, ratio === '1:1' ? 2.5 : 3, accent);
  ctx.restore();
  plan.push({ n: 'radar', x1: 375 - extent2, x2: 375 + extent2, y1: radarCy - extent2, y2: radarCy + extent2 });
  y = radarBox.bottom;

  /* 8. 页脚：真实二维码 + 引导（底部锚定） */
  ctx.strokeStyle = 'rgba(255,255,255,0.10)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(120, footTop); ctx.lineTo(630, footTop); ctx.stroke();
  const qrSize = C.qr;
  const qrTop = footTop + (footH - qrSize) / 2 - 2;
  drawQr(ctx, 78, qrTop, qrSize, fig.name.charCodeAt(0));
  plan.push({ n: 'qr', x1: 72, x2: 78 + qrSize + 6, y1: qrTop - 6, y2: qrTop + qrSize + 6 });
  const tx = 78 + qrSize + (ratio === '1:1' ? 20 : 26);
  T('扫码测测你像谁', ratio === '1:1' ? 22 : 27, P.ink, qrTop + (ratio === '1:1' ? 26 : 32), '600', 'left', tx);
  T('hdhhduehdwbdf.github.io/wzry-persona-quiz', ratio === '1:1' ? 15 : 18, accent, qrTop + (ratio === '1:1' ? 48 : 60), '500', 'left', tx);
  if (ratio !== '1:1') T('完全免费 · 手机即开 · 扫码即测', 17, P.ink3, qrTop + 84, '400', 'left', tx);
  T('趣味测试 · 非官方授权', ratio === '1:1' ? 13 : 15, P.ink3, H - inset - 10);

  window.__shareLayout = { ratio, W, H, plan };
}

/* 雷达图（人物专属主色版）：供分享卡片使用 */
function drawRadarShapeAccent(ctx, cx, cy, R, scores, labelFont, lineWidth, accent) {
  const n = DIMS.length;
  const pt = (i, r) => {
    const a = -Math.PI / 2 + i * 2 * Math.PI / n;
    return [cx + Math.cos(a) * r, cy + Math.sin(a) * r];
  };
  ctx.strokeStyle = 'rgba(255,255,255,0.13)'; ctx.lineWidth = 1;
  for (let ring = 1; ring <= 4; ring++) {
    ctx.beginPath();
    for (let i = 0; i <= n; i++) { const [x, y] = pt(i % n, R * ring / 4); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }
    ctx.stroke();
  }
  for (let i = 0; i < n; i++) { const [x, y] = pt(i, R); ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(x, y); ctx.stroke(); }
  ctx.beginPath();
  for (let i = 0; i <= n; i++) { const d = DIMS[i % n]; const [x, y] = pt(i % n, R * scores[d] / 100); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }
  ctx.closePath();
  ctx.save();
  ctx.globalAlpha = 0.16; ctx.fillStyle = accent; ctx.fill();
  ctx.globalAlpha = 1; ctx.strokeStyle = accent; ctx.lineWidth = lineWidth; ctx.stroke();
  for (let i = 0; i < n; i++) {
    const [x, y] = pt(i, R * scores[DIMS[i]] / 100);
    ctx.beginPath(); ctx.arc(x, y, lineWidth + 1, 0, Math.PI * 2); ctx.fillStyle = accent; ctx.fill();
  }
  ctx.restore();
  ctx.fillStyle = P.ink2;
  ctx.font = '500 ' + labelFont + 'px ' + FONT;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  DIMS.forEach((d, i) => { const [x, y] = pt(i, R + labelFont * 1.8); ctx.fillText(d, x, y); });
  ctx.textBaseline = 'alphabetic';
  return { top: cy - R - labelFont * 2.4, bottom: cy + R + labelFont * 2.4 };
}


